export interface ManufacturerDto {
  id: number | null;
  name: string;
  cars?: CarDto[];
}

export interface CarDto {
  id: number | null;
  model: string;
  manufacturer: ManufacturerDto | null;
}

export interface RatingDto {
  id: number | null;
  rating: number | null;
  car: CarDto | null;
}

export interface ManufacturerRatingDto {
  manufacturer: string;
  rating: number;
}

/** Same text as RatingDto.toString() in the GWT app: "Manufacturer/Model". */
export function carLabel(car: CarDto | null | undefined): string {
  if (!car) {
    return '';
  }
  return car.manufacturer ? `${car.manufacturer.name}/${car.model}` : car.model;
}
