import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { CarDto, ManufacturerDto, ManufacturerRatingDto, RatingDto } from './models';

/** Thin wrapper over the existing JSON REST API served at /api (see gwt/.../shared/api). */
@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient);

  getManufacturers(): Observable<ManufacturerDto[]> {
    return this.http.get<ManufacturerDto[]>('/api/manufacturers');
  }

  saveManufacturer(manufacturer: ManufacturerDto): Observable<ManufacturerDto> {
    return this.http.post<ManufacturerDto>('/api/manufacturers', manufacturer);
  }

  deleteManufacturer(id: number): Observable<void> {
    return this.http.delete<void>(`/api/manufacturers/${id}`);
  }

  getAverageRatings(): Observable<ManufacturerRatingDto[]> {
    return this.http.get<ManufacturerRatingDto[]>('/api/manufacturers/rating');
  }

  getCars(): Observable<CarDto[]> {
    return this.http.get<CarDto[]>('/api/cars', { params: { offset: 0, limit: -1 } });
  }

  getRatings(): Observable<RatingDto[]> {
    return this.http.get<RatingDto[]>('/api/ratings');
  }

  saveRating(rating: RatingDto): Observable<RatingDto> {
    return this.http.post<RatingDto>('/api/ratings', rating);
  }

  deleteRating(id: number): Observable<void> {
    return this.http.delete<void>(`/api/ratings/${id}`);
  }
}
EOF
