      <thead>
        <tr><th>ID</th><th>Name</th><th>Edit</th><th>Delete</th></tr>
      </thead>
      <tbody>
        @for (manufacturer of manufacturers(); track manufacturer.id ?? $index) {
          <tr>
            <td>{{ manufacturer.id }}</td>
            <td>{{ manufacturer.name }}</td>
            <td><button type="button" (click)="edit(manufacturer)">Edit</button></td>
            <td><button type="button" (click)="remove(manufacturer)">Delete</button></td>
          </tr>
        }
      </tbody>
    </table>
    @if (editorOpen()) {
      <app-edit-manufacturer [manufacturer]="editTarget()" (saved)="onSaved($event)" (closed)="editorOpen.set(false)" />
    }
  `,
  styles: `
    .title-row { display: flex; align-items: center; justify-content: space-between; }
  `,
})
export class ManufacturerComponent implements OnInit {
  readonly manufacturers = signal<ManufacturerDto[]>([]);
  readonly editorOpen = signal(false);
  readonly editTarget = signal<ManufacturerDto | null>(null);

  private readonly api = inject(ApiService);
  private readonly messages = inject(MessageService);

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({
      next: (list) => this.manufacturers.set(list),
      error: () => this.messages.error('Could not load manufacturers'),
    });
  }

  create(): void {
    this.editTarget.set(null);
    this.editorOpen.set(true);
  }

  edit(manufacturer: ManufacturerDto): void {
    this.editTarget.set(manufacturer);
    this.editorOpen.set(true);
  }

  onSaved(saved: ManufacturerDto): void {
    this.manufacturers.update((list) => {
      const index = list.findIndex((m) => m.id !== null && m.id === saved.id);
      if (index >= 0) {
        return list.map((m, i) => (i === index ? saved : m));
      }
      return [...list, saved];
    });
  }

  remove(manufacturer: ManufacturerDto): void {
    if (manufacturer.id === null) {
      return;
    }
    if (!window.confirm(`Are you sure you want to delete ${manufacturer.name}?`)) {
      return;
    }
    const id = manufacturer.id;
    this.api.deleteManufacturer(id).subscribe({
      next: () => this.manufacturers.update((list) => list.filter((m) => m.id !== id)),
      error: () => this.messages.error('Could not delete the manufacturer'),
    });
  }
}
