import com.gwtplatform.carstore.cucumber.application.widgets.HeaderWidgetPage;
import com.gwtplatform.carstore.cucumber.application.widgets.MessageWidgetPage;
import com.gwtplatform.carstore.cucumber.util.TestParameters;

import cucumber.api.java.en.Given;
import cucumber.api.java.en.Then;
import cucumber.api.java.en.When;
import cucumber.runtime.java.guice.ScenarioScoped;

import static com.gwtplatform.carstore.client.debug.DebugIds.DBG_MENUBAR;
import static org.junit.Assert.assertTrue;

/** Glue for the steps the features use but the repo does not define: login (no-op, API is open) and navigation. */
@ScenarioScoped
public class NavigationStepDefs extends StepDefs {
    private final WebDriver webDriver;
    private final HeaderWidgetPage headerWidgetPage;
    private final MessageWidgetPage messageWidgetPage;

    @Inject
    NavigationStepDefs(WebDriver webDriver, HeaderWidgetPage headerWidgetPage, MessageWidgetPage messageWidgetPage) {
        this.webDriver = webDriver;
        this.headerWidgetPage = headerWidgetPage;
        this.messageWidgetPage = messageWidgetPage;
    }

    @Given("^I'm logged in$")
    public void iAmLoggedIn() {
        webDriver.get(TestParameters.BASE_URL);
        new WebDriverWait(webDriver, TestParameters.TIME_OUT_IN_SECONDS)
                .until(ExpectedConditions.visibilityOfElementLocated(By.id("gwt-debug-" + DBG_MENUBAR)));
    }

    @Given("^I navigate to the manufacturer page$")
    public void iNavigateToManufacturerPage() {
        headerWidgetPage.navigateTo("manufacturer");
    }

    @Given("^I navigate to the rating page$")
    public void iNavigateToRatingPage() {
        headerWidgetPage.navigateTo("rating");
    }

    @When("^I navigate to the report page$")
    public void iNavigateToReportPage() {
        headerWidgetPage.navigateTo("report");
    }

    @Then("^I see a success message containing (\\S+)$")
    public void iSeeASuccessMessageContaining(String text) {
        assertTrue(messageWidgetPage.hasSuccessMessage(text));
    }
}
