package com.gwtplatform.carstore.cucumber;

import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;

import com.google.inject.AbstractModule;
import com.google.inject.Guice;
import com.google.inject.Injector;
import com.google.inject.Singleton;

import cucumber.runtime.java.guice.InjectorSource;

public class CucumberInjectorSource implements InjectorSource {
    private static WebDriver driver;

    @Override
    public Injector getInjector() {
        return Guice.createInjector(new AbstractModule() {
            @Override
            protected void configure() {
                bind(WebDriver.class).toInstance(webDriver());
            }
        });
    }

    private static synchronized WebDriver webDriver() {
        if (driver == null) {
            ChromeOptions options = new ChromeOptions();
            options.setBinary(System.getProperty("chrome.binary", "/usr/bin/chromium"));
            options.addArguments("--headless", "--no-sandbox", "--disable-gpu", "--window-size=1280,1024");
            driver = new ChromeDriver(options);
            Runtime.getRuntime().addShutdownHook(new Thread(driver::quit));
        }
        return driver;
    }
}
